/**
 * @name GoldenMoss
 * @author Codex
 * @description Архивный лес, оливковая палитра и настраиваемые матовые панели Discord.
 * @version 1.4.3
 */

/* =====================================
   GOLDEN MOSS — USER CONFIGURATION
   Меняйте только значения между двоеточием и точкой с запятой.
   Сохраните файл. Если изменения не появились, выключите и снова включите тему.
   ===================================== */
:root {
  /* Обои */
  --gm-wallpaper-image: embedded;       /* embedded — встроенный лес, url("https://…") — своя картинка, none — однотонный фон. */
  --gm-wallpaper-x: 0.5;               /* Горизонтальное кадрирование. 0 — левый край, 1 — правый. */
  --gm-wallpaper-y: 0.5;               /* Вертикальное кадрирование. 0 — верхний край, 1 — нижний. */
  --gm-wallpaper-position: var(--gm-mapped-position); /* Для эффектов меняйте координаты выше. */
  --gm-wallpaper-size: cover;           /* cover — заполнить окно, contain — уместить всю картинку. */
  --gm-wallpaper-dim: 0.16;            /* Затемнение картинки целиком. 0 — исходная яркость, 0.25 — затемнить на 25%. */

  /* Цвета. Можно вводить любой цвет в формате #RRGGBB. */
  --gm-bg-deep: #192319;               /* Основной тёмный оттенок и фон при отключённых обоях. */
  --gm-bg-secondary: #303B24;          /* Оливковый оттенок боковых панелей, карточек и полей. */
  --gm-olive-dark: #52633A;             /* Выбранный канал, основные кнопки и выделение текста. */
  --gm-olive: #82905D;                  /* Подсветка при наведении и рамка выбранных реакций. */
  --gm-accent: #B2B58A;                 /* Акцентные значки, полоски упоминаний и рамка фокуса. */
  --gm-accent-light: #D5D3AD;           /* Ссылки, упоминания в тексте и светлые акценты. */
  --gm-text-primary: #E8E6CE;           /* Основной текст и заголовки. */
  --gm-text-secondary: #A7AC90;        /* Цвет, из которого получаются подписи и второстепенный текст. */
  --gm-text-muted: #7F896F;             /* Приглушённые значки и часть цвета мелких подписей. */
  --gm-border: #414B34;                 /* Линии между панелями, рамки окон и полей. */
  --gm-online: #7FA56A;                 /* Индикатор «В сети». */

  /* Подложки. Чем меньше число, тем лучше виден лес. 0 — полностью прозрачная подложка, 1 — сплошная. */
  --gm-guilds-opacity: 0.62;           /* Самая левая полоса со значками серверов. */
  --gm-channels-opacity: 0.42;         /* Список каналов внутри сервера. */
  --gm-dm-opacity: 0.43;               /* Список личных сообщений слева на главной странице. */
  --gm-chat-opacity: 0.33;             /* Большая область переписки по центру и список друзей. */
  --gm-call-opacity: 0.48;             /* Подложка вокруг трансляции. 0 — видны только обои, 1 — сплошной тёмно-зелёный фон. */
  --gm-members-opacity: 0.42;          /* Список участников сервера справа. */
  --gm-activity-opacity: 0.42;         /* Колонка «Активные контакты» на странице друзей. */
  --gm-profile-opacity: 0.60;          /* Панель с профилем собеседника справа в личном чате. */
  --gm-header-opacity: 0.65;           /* Верхняя полоса окна, шапка канала и нижний блок с микрофоном. */
  --gm-input-opacity: 0.72;            /* Поле набора сообщения. */
  --gm-popout-opacity: 0.82;           /* Контекстные меню, всплывающие карточки профилей и диалоги. */
  --gm-settings-opacity: 0.40;         /* Само окно настроек. */
  --gm-settings-scrim-opacity: 0.16;   /* Затемнение вокруг окна настроек, пока оно открыто. 0 — без затемнения. */

  /* Шрифты и оформление */
  --gm-glass-filter: none;              /* Размытие под открытыми настройками. blur(4px) — включить. */
  --gm-font-family: "IBM Plex Sans", "Segoe UI", sans-serif; /* Шрифты по порядку. Для шрифта Discord укажите "gg sans", sans-serif. */
  --gm-font-scale: 1;                   /* Размер текста сообщений и поля ввода. 1 — размер Discord, 1.10 — на 10% крупнее. */
  --gm-radius-small: 8px;               /* Скругление строк каналов, реакций и небольших карточек. */
  --gm-radius-medium: 12px;             /* Скругление поля ввода, меню и обычных диалогов. */
  --gm-radius-large: 16px;              /* Скругление окна настроек и профилей. */
  --gm-shadow: none;                    /* Тени окон и меню. Пример мягкой тени — 0 6px 18px rgb(0 0 0 / 0.28). */
  --gm-transition-duration: 0ms;        /* Скорость смены цвета при наведении. 140ms — плавный переход. */

  /* Живой лес. Для любого эффекта none полностью останавливает анимацию.
     Время в секундах задаёт длительность цикла. Чем оно больше, тем медленнее движение. */
  --gm-effects-mode: full;           /* static — стоп, ambient — мягкое движение, full — ярче и с падающим листом. */
  --gm-mist-animation: gm-mist-drift 42s ease-in-out infinite alternate; /* Дымка в лесу и перед руинами. */
  --gm-rays-animation: gm-rays-breathe 13s ease-in-out infinite;       /* Качание и яркость лучей под кроной. */
  --gm-arch-ray-animation: gm-arch-ray 11s ease-in-out infinite;        /* Маленький луч в самой правой арке. */
  --gm-fireflies-animation: gm-firefly 13s ease-in-out infinite;       /* Движение и мерцание светлячков. */
  --gm-dust-animation: gm-dust-drift 15s ease-in-out infinite alternate; /* Дрейф пылинок. */
  --gm-leaves-animation: initial;       /* initial — по режиму, none — убрать листья. Для ручного включения используйте gm-leaf 22s linear infinite. */
  --gm-eyes-animation: gm-eyes-blink 26s linear infinite;               /* Появление и моргание глаз. */

  --gm-mist-opacity: 0.24;              /* Яркость обеих полос дымки. */
  --gm-rays-opacity: 0.28;              /* Яркость солнечных лучей под кроной. */
  --gm-arch-ray-opacity: 0.29;          /* Яркость маленького луча в правой арке. */
  --gm-fireflies-opacity: 0.63;         /* Три точки света возле руин. */
  --gm-dust-opacity: 0.64;              /* Светлые пылинки в просвете между деревьями. */
  --gm-leaves-opacity: 0.94;            /* Яркость листа во время падения. */
  --gm-eyes-opacity: 0.86;              /* Яркость одной пары глаз в стволе. */
  --gm-eyes-x: 520;                     /* Координата слева на исходных обоях шириной 2560 px. */
  --gm-eyes-y: 663;                     /* Координата сверху на исходных обоях высотой 1440 px. */
  --gm-eyes-scale: 1;                   /* Размер глаз. Например, 0.8 уменьшает их на 20%. */
}

/* Theme Tokens */
/* Chromium вычисляет эти производные цвета на корне. Строки чата наследуют готовые цвета. */
@property --gm-readable-secondary {
  syntax: "<color>";
  inherits: true;
  initial-value: #bebeaa;
}

@property --gm-label-muted {
  syntax: "<color>";
  inherits: true;
  initial-value: #bbbba7;
}

@property --gm-hover {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --gm-message-hover {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --gm-divider {
  syntax: "<color>";
  inherits: true;
  initial-value: #414b34;
}

:root {
  --gm-mapped-position: calc(100% * var(--gm-wallpaper-x)) calc(100% * var(--gm-wallpaper-y));
  --gm-panel-olive: color-mix(in srgb, var(--gm-bg-secondary) 62%, var(--gm-bg-deep));
  --gm-surface-guilds: color-mix(in srgb, var(--gm-bg-deep) calc(var(--gm-guilds-opacity) * 100%), transparent);
  --gm-surface-channels: color-mix(in srgb, var(--gm-panel-olive) calc(var(--gm-channels-opacity) * 100%), transparent);
  --gm-surface-dm: color-mix(in srgb, var(--gm-panel-olive) calc(var(--gm-dm-opacity) * 100%), transparent);
  --gm-surface-chat: color-mix(in srgb, var(--gm-bg-deep) calc(var(--gm-chat-opacity) * 100%), transparent);
  --gm-surface-call: color-mix(in srgb, var(--gm-bg-deep) calc(var(--gm-call-opacity) * 100%), transparent);
  --gm-surface-members: color-mix(in srgb, var(--gm-panel-olive) calc(var(--gm-members-opacity) * 100%), transparent);
  --gm-surface-activity: color-mix(in srgb, var(--gm-panel-olive) calc(var(--gm-activity-opacity) * 100%), transparent);
  --gm-surface-profile: color-mix(in srgb, var(--gm-panel-olive) calc(var(--gm-profile-opacity) * 100%), transparent);
  --gm-surface-header: color-mix(in srgb, var(--gm-bg-deep) calc(var(--gm-header-opacity) * 100%), transparent);
  --gm-surface-input: color-mix(in srgb, var(--gm-panel-olive) calc(var(--gm-input-opacity) * 100%), transparent);
  --gm-surface-popout: color-mix(in srgb, var(--gm-bg-deep) calc(var(--gm-popout-opacity) * 100%), transparent);
  --gm-surface-settings: color-mix(in srgb, var(--gm-bg-deep) calc(var(--gm-settings-opacity) * 100%), transparent);
  --gm-surface-inset: color-mix(in srgb, var(--gm-bg-deep) 30%, transparent);
  --gm-account-section: color-mix(in srgb, var(--gm-panel-olive) calc(var(--gm-popout-opacity) * 100%), transparent);
  --gm-settings-scrim: rgb(0 0 0 / clamp(0, var(--gm-settings-scrim-opacity), 1));

  --gm-readable-secondary: color-mix(in srgb, var(--gm-text-secondary) 65%, var(--gm-text-primary));
  --gm-label-muted: color-mix(in srgb, var(--gm-readable-secondary) 94%, var(--gm-text-muted));
  --gm-hover: color-mix(in srgb, var(--gm-olive) 16%, transparent);
  --gm-message-hover: color-mix(in srgb, var(--gm-accent) 6%, transparent);
  --gm-mention: color-mix(in srgb, var(--gm-accent) 13%, transparent);
  --gm-mention-hover: color-mix(in srgb, var(--gm-accent) 19%, transparent);
  --gm-reacted: color-mix(in srgb, var(--gm-olive) 27%, transparent);
  --gm-reacted-hover: color-mix(in srgb, var(--gm-olive) 36%, transparent);
  --gm-brand-hover: color-mix(in srgb, var(--gm-olive-dark) 82%, var(--gm-olive));
  --gm-brand-active: color-mix(in srgb, var(--gm-olive-dark) 76%, var(--gm-bg-deep));
  --gm-divider: color-mix(in srgb, var(--gm-border) 75%, transparent);
  --gm-motion: var(--gm-transition-duration);
}

/* Performance Presets
   Balanced — значения выше. Готовые блоки Performance и Visual находятся в README.md.
   Вставьте один из блоков в BetterDiscord → Custom CSS или замените значения выше. */

/* Discord Variable Overrides */
:is(html, body):is(.theme-dark, .theme-darker, .theme-midnight, .theme-light),
#app-mount,
#app-mount :is(.theme-dark, .theme-darker, .theme-midnight, .theme-light):not(:where(.custom-user-profile-theme, .custom-theme-background, .custom-user-profile-theme *, .custom-theme-background *)) {
  --background-base-lowest: var(--gm-bg-deep);
  --background-base-lower: var(--gm-bg-deep);
  --background-base-low: var(--gm-bg-secondary);
  --background-surface-high: var(--gm-bg-secondary);
  --background-surface-higher: var(--gm-bg-secondary);
  --background-surface-highest: var(--gm-bg-secondary);
  --bg-base-primary: var(--gm-bg-deep);
  --bg-base-secondary: var(--gm-bg-secondary);
  --bg-base-tertiary: var(--gm-bg-deep);
  --bg-surface-raised: var(--gm-bg-secondary);
  --bg-surface-overlay: var(--gm-surface-popout);
  --bg-surface-overlay-tmp: var(--gm-surface-popout);
  --bg-floating: var(--gm-surface-popout);
  --background-primary: var(--gm-bg-deep);
  --background-secondary: var(--gm-bg-secondary);
  --background-secondary-alt: var(--gm-bg-secondary);
  --background-tertiary: var(--gm-bg-deep);
  --background-floating: var(--gm-surface-popout);
  --background-nested-floating: var(--gm-bg-secondary);
  --background-mod-muted: var(--gm-hover);
  --background-mod-subtle: var(--gm-hover);
  --background-mod-normal: var(--gm-bg-secondary);
  --background-mod-strong: var(--gm-bg-secondary);
  --background-modifier-hover: var(--gm-hover);
  --background-modifier-active: var(--gm-olive-dark);
  --background-modifier-selected: var(--gm-olive-dark);
  --background-modifier-accent: var(--gm-divider);
  --interactive-background-hover: var(--gm-hover);
  --interactive-background-active: var(--gm-olive-dark);
  --interactive-background-selected: var(--gm-olive-dark);
  --card-background-default: var(--gm-bg-secondary);
  --card-secondary-bg: var(--gm-bg-deep);
  --modal-background: var(--gm-surface-popout);
  --modal-footer-background: var(--gm-bg-secondary);
  --panel-bg: var(--gm-bg-secondary);
  --input-background: var(--gm-bg-deep);
  --input-background-default: var(--gm-bg-deep);
  --input-border-default: var(--gm-border);
  --input-border-hover: var(--gm-olive);
  --input-border-active: var(--gm-accent);
  --input-placeholder-text-default: var(--gm-label-muted);
  --input-text-default: var(--gm-text-primary);
  --border-subtle: var(--gm-divider);
  --border-muted: var(--gm-divider);
  --border-normal: var(--gm-border);
  --border-strong: var(--gm-olive-dark);
  --border-focus: var(--gm-accent);
  --focus-primary: var(--gm-accent-light);
  --scrollbar-auto-thumb: var(--gm-olive-dark);
  --scrollbar-auto-track: transparent;
  --scrollbar-thin-thumb: var(--gm-olive-dark);
  --scrollbar-thin-track: transparent;
  --radius-sm: var(--gm-radius-small);
  --radius-md: var(--gm-radius-medium);
  --radius-lg: var(--gm-radius-large);

  --text-strong: var(--gm-text-primary);
  --text-default: var(--gm-text-primary);
  --text-normal: var(--gm-text-primary);
  --text-secondary: var(--gm-readable-secondary);
  --text-subtle: var(--gm-readable-secondary);
  --text-tertiary: var(--gm-label-muted);
  --text-muted: var(--gm-label-muted);
  --text-link: var(--gm-accent-light);
  --text-brand: var(--gm-accent-light);
  --header-primary: var(--gm-text-primary);
  --header-secondary: var(--gm-readable-secondary);
  --interactive-normal: var(--gm-readable-secondary);
  --interactive-hover: var(--gm-text-primary);
  --interactive-active: var(--gm-text-primary);
  --interactive-text-default: var(--gm-readable-secondary);
  --interactive-text-hover: var(--gm-text-primary);
  --interactive-text-active: var(--gm-text-primary);
  --interactive-icon-default: var(--gm-text-secondary);
  --interactive-icon-hover: var(--gm-accent-light);
  --interactive-icon-active: var(--gm-text-primary);
  --icon-default: var(--gm-text-secondary);
  --icon-muted: var(--gm-text-muted);
  --icon-subtle: var(--gm-label-muted);
  --icon-strong: var(--gm-text-primary);
  --status-online: var(--gm-online);
  --icon-status-online: var(--gm-online);

  /* Акцентные кнопки. Критические, предупреждающие и голосовые состояния используют штатные токены. */
  --brand-400: var(--gm-accent);
  --brand-500: var(--gm-olive-dark);
  --brand-560: var(--gm-brand-hover);
  --brand-600: var(--gm-brand-active);
  --brand-experiment: var(--gm-olive-dark);
  --background-brand: var(--gm-olive-dark);
  --control-brand-foreground: var(--gm-accent-light);
  --control-primary-background-default: var(--gm-olive-dark);
  --control-primary-background-hover: var(--gm-brand-hover);
  --control-primary-background-active: var(--gm-brand-active);
  --control-primary-text-default: var(--gm-text-primary);
  --control-primary-text-hover: var(--gm-text-primary);
  --control-primary-text-active: var(--gm-text-primary);
  --control-primary-icon-default: var(--gm-text-primary);
  --control-primary-icon-hover: var(--gm-text-primary);
  --control-primary-icon-active: var(--gm-text-primary);
  --control-secondary-background-default: var(--gm-bg-secondary);
  --control-secondary-background-hover: var(--gm-hover);
  --control-secondary-background-active: var(--gm-olive-dark);
  --button-filled-brand-background: var(--gm-olive-dark);
  --button-filled-brand-background-hover: var(--gm-brand-hover);
  --button-filled-brand-background-active: var(--gm-brand-active);
  --button-filled-brand-text: var(--gm-text-primary);
  --redesign-button-primary-background: var(--gm-olive-dark);
  --redesign-button-primary-pressed-background: var(--gm-brand-active);
  --redesign-button-primary-text: var(--gm-text-primary);
}

/* Фон окна находится под декоративными слоями BetterDiscord. */
html {
  background-color: var(--gm-bg-deep);
}

body {
  background-color: rgb(0 0 0 / clamp(0, var(--gm-wallpaper-dim), 1));
  background-image: var(--gm-wallpaper-image);
  background-blend-mode: multiply;
  background-position: var(--gm-wallpaper-position);
  background-size: var(--gm-wallpaper-size);
  background-repeat: no-repeat;
}

#app-mount {
  background: transparent;
}

@container style(--gm-wallpaper-image: none) {
  body {
    background-color: var(--gm-bg-deep);
  }
}

/* Маленькие накладки привязаны к пикселям оригинала. Служебные узлы BetterDiscord
   находятся вне интерфейса приложения. Их псевдоэлементы рисуются под ним. */
@media (prefers-reduced-motion: no-preference) and (forced-colors: none) {
  @container style(--gm-wallpaper-image: embedded) and style(--gm-wallpaper-position: var(--gm-mapped-position)) and (style(--gm-wallpaper-size: cover) or style(--gm-wallpaper-size: contain)) and (style(--gm-effects-mode: ambient) or style(--gm-effects-mode: full)) {
    body {
      isolation: isolate;
      --gm-fx-unit: max(100dvw / 2560, 100dvh / 1440);
      --gm-fx-left: calc((100dvw - 2560 * var(--gm-fx-unit)) * var(--gm-wallpaper-x));
      --gm-fx-top: calc((100dvh - 1440 * var(--gm-fx-unit)) * var(--gm-wallpaper-y));
      --gm-fx-gain: 1;
      --gm-leaves-preset: none;
    }

    @container style(--gm-wallpaper-size: contain) {
      body { --gm-fx-unit: min(100dvw / 2560, 100dvh / 1440); }
    }

    @container style(--gm-effects-mode: full) {
      body {
        --gm-fx-gain: 1.4;
        --gm-leaves-preset: gm-leaf 22s linear infinite;
      }
    }

    body > bd-head,
    body > bd-head > :is(bd-scripts, bd-styles) {
      display: contents;
    }

    body::before, body::after,
    body > bd-body::before, body > bd-body::after,
    body > bd-head::before, body > bd-head::after,
    body > bd-head > :is(bd-scripts, bd-styles)::before,
    body > bd-head > :is(bd-scripts, bd-styles)::after {
      content: "";
      position: fixed;
      z-index: -1;
      pointer-events: none;
      top: calc(var(--gm-fx-top) + var(--gm-fx-y) * var(--gm-fx-unit));
      left: calc(var(--gm-fx-left) + var(--gm-fx-x) * var(--gm-fx-unit));
      width: calc(var(--gm-fx-w) * var(--gm-fx-unit));
      height: calc(var(--gm-fx-h) * var(--gm-fx-unit));
      opacity: 0;
      background-repeat: no-repeat;
    }

    /* Две местные полосы дымки с разной фазой и размахом дрейфа. */
    body::before,
    body > bd-body::before {
      --gm-fx-peak: clamp(0, var(--gm-mist-opacity) * var(--gm-fx-gain) * var(--gm-mist-density, 1), 1);
      background:
        radial-gradient(ellipse 49% 24% at 47% 64%, #cfccade0, #b7b68a82 43%, #a8aa762b 70%, transparent),
        radial-gradient(ellipse 46% 31% at 59% 43%, #c1c39ac9, #b0b08861 46%, transparent);
      animation: var(--gm-mist-animation);
    }

    body::before {
      --gm-fx-x: 716;
      --gm-fx-y: 515;
      --gm-fx-w: 924;
      --gm-fx-h: 360;
      animation-delay: -9s;
    }

    body > bd-body::before {
      --gm-fx-x: 1540;
      --gm-fx-y: 724;
      --gm-fx-w: 653;
      --gm-fx-h: 222;
      --gm-mist-density: 0.86;
      --gm-mist-travel: 0.56;
      animation-delay: -19s;
    }

    body::after {
      --gm-fx-x: 1072;
      --gm-fx-y: 164;
      --gm-fx-w: 660;
      --gm-fx-h: 625;
      --gm-fx-peak: clamp(0, var(--gm-rays-opacity) * var(--gm-fx-gain), 1);
      background: linear-gradient(137deg,
        transparent 38%, #e5ce884d 44%, #e4ca884a 48%, transparent 52%,
        #eed5a075 54%, #f0d999ed 57%, #f0d99996 61%, transparent 69%);
      mask-image: radial-gradient(ellipse 53% 59% at 56% 42%, #000 22%, transparent 97%);
      transform-origin: 82% 9%;
      animation: var(--gm-rays-animation);
      animation-delay: -1.5s;
    }

    /* Контур ограничен внутренней частью правой арки. */
    body > bd-body::after {
      --gm-fx-x: 2219;
      --gm-fx-y: 451;
