        linear-gradient(120deg, transparent 29%, #e0ce8a34 36%, #f2dba8d9 46%, #ecd69e61 54%, transparent 70%),
        radial-gradient(ellipse 65% 20% at 32% 92%, #e3cc9666, transparent);
