    }

    body > bd-head::before {
      --gm-fx-x: 930;
      --gm-fx-y: 382;
      --gm-fx-w: 627;
      --gm-fx-h: 431;
      --gm-fx-peak: clamp(0, var(--gm-dust-opacity) * var(--gm-fx-gain), 1);
