        var(--gm-dust-grain) 88% 20% / 1.75% 2.55% no-repeat;
      animation: var(--gm-dust-animation);
      animation-delay: -4s;
    }

    /* Два глаза в выемке. Текстура каждой половины содержит зрачок и радужку. */
    body > bd-head::after {
      --gm-fx-x: calc(var(--gm-eyes-x) - 15 * var(--gm-eyes-scale));
