      animation: var(--gm-eyes-animation);
    }

    body > bd-head > bd-scripts::before,
    body > bd-head > bd-scripts::after,
    body > bd-head > bd-styles::before {
      --gm-fx-w: 20;
      --gm-fx-h: 20;
